package com.mg.machineelementspro;

import android.app.Activity;
import android.graphics.*;
import android.os.Bundle;
import android.text.*;
import android.view.View;
import android.widget.*;
import java.util.Locale;

public class MachineElementVisualLabActivity extends Activity {
    private final EditText[] in=new EditText[6];
    private Diagram d;
    private int mode=0;
    private static final String[] MODES={"Mil","Rulman","Civata"};
    private static final String[][] HINTS={{"M (N·m)","T (N·m)","d (mm)","Sy (MPa)","L (mm)","Yük konumu a (mm)"},{"Fr / P (N)","Fa (N)","C (N)","n (rpm)","Mil çapı (mm)",""},{"F eksenel (N)","V kesme (N)","d (mm)","Sy (MPa)","Bağlantı kalınlığı (mm)",""}};
    @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(build());select(0);}
    private View build(){ScrollView s=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(14),dp(16),dp(14),dp(24));s.addView(r);r.addView(t("VISUAL ENGINEERING LAB",22,true));r.addView(t("Girdi değiştikçe ölçü, yük, reaksiyon ve kritik bölge görsel üzerinde güncellenir.",14,false));LinearLayout tabs=new LinearLayout(this);for(int i=0;i<3;i++){final int x=i;Button b=new Button(this);b.setText(MODES[i]);b.setAllCaps(false);b.setOnClickListener(v->select(x));tabs.addView(b,new LinearLayout.LayoutParams(0,dp(50),1));}r.addView(tabs);for(int i=0;i<6;i++){in[i]=new EditText(this);in[i].setSingleLine();in[i].setInputType(2|8192|16384);in[i].addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){if(d!=null){d.v=vals();d.invalidate();}}public void afterTextChanged(Editable e){}});r.addView(in[i],new LinearLayout.LayoutParams(-1,dp(52)));}d=new Diagram();r.addView(d,new LinearLayout.LayoutParams(-1,dp(360)));Button old=new Button(this);old.setText("TÜM MAKİNE ELEMANLARI GALERİSİ");old.setAllCaps(false);old.setOnClickListener(v->startActivity(new android.content.Intent(this,MachineElementStudioActivity.class)));r.addView(old);return s;}
    private void select(int m){mode=m;for(int i=0;i<6;i++){in[i].setHint(HINTS[m][i]);in[i].setVisibility(HINTS[m][i].isEmpty()?View.GONE:View.VISIBLE);in[i].setText("");}if(d!=null){d.v=vals();d.invalidate();}}
    private double[] vals(){double[] v=new double[6];for(int i=0;i<6;i++){try{v[i]=Double.parseDouble(in[i].getText().toString().trim().replace(',','.'));}catch(Exception ignored){}}return v;}
    private TextView t(String s,int z,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(Color.rgb(20,30,45));if(b)x.setTypeface(Typeface.DEFAULT_BOLD);x.setPadding(0,dp(4),0,dp(8));return x;}
    private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
    private class Diagram extends View{double[] v=new double[6];Paint p=new Paint(1),tx=new Paint(1);Diagram(){super(MachineElementVisualLabActivity.this);setBackgroundColor(Color.rgb(18,25,33));tx.setTypeface(Typeface.DEFAULT_BOLD);}protected void onDraw(Canvas c){super.onDraw(c);grid(c);if(mode==0)shaft(c);else if(mode==1)bearing(c);else bolt(c);}void grid(Canvas c){p.setStrokeWidth(1);p.setColor(Color.rgb(37,49,61));for(int x=0;x<getWidth();x+=dp(24))c.drawLine(x,0,x,getHeight(),p);for(int y=0;y<getHeight();y+=dp(24))c.drawLine(0,y,getWidth(),y,p);}void line(Canvas c,int col,float sw,float x1,float y1,float x2,float y2){p.setColor(col);p.setStrokeWidth(sw);p.setStyle(Paint.Style.STROKE);c.drawLine(x1,y1,x2,y2,p);p.setStyle(Paint.Style.FILL);}void lab(Canvas c,String s,float x,float y,int col){tx.setTextSize(dp(12));tx.setColor(col);c.drawText(s,x,y,tx);}void arrow(Canvas c,float x1,float y1,float x2,float y2,int col,String s){line(c,col,dp(3),x1,y1,x2,y2);double a=Math.atan2(y2-y1,x2-x1);float L=dp(10);Path q=new Path();q.moveTo(x2,y2);q.lineTo((float)(x2-L*Math.cos(a-.55)),(float)(y2-L*Math.sin(a-.55)));q.lineTo((float)(x2-L*Math.cos(a+.55)),(float)(y2-L*Math.sin(a+.55)));q.close();p.setColor(col);c.drawPath(q,p);lab(c,s,x2+dp(4),y2,col);}void dim(Canvas c,float x1,float x2,float y,String s){line(c,Color.LTGRAY,1,x1,y,x2,y);line(c,Color.LTGRAY,1,x1,y-dp(7),x1,y+dp(7));line(c,Color.LTGRAY,1,x2,y-dp(7),x2,y+dp(7));lab(c,s,(x1+x2)/2-dp(18),y-dp(5),Color.WHITE);}String f(double x){return String.format(Locale.US,"%.1f",x);}void shaft(Canvas c){float w=getWidth(),h=getHeight(),y=h*.52f,xA=w*.14f,xB=w*.86f,xF=w*.56f;double L=v[4]>0?v[4]:500,a=v[5]>0?v[5]:L*.58;xF=(float)(xA+(xB-xA)*Math.max(0,Math.min(1,a/L)));line(c,Color.LTGRAY,dp(18),xA,y,xB,y);p.setColor(Color.rgb(100,116,139));c.drawRect(xA-dp(13),y-dp(33),xA+dp(13),y+dp(33),p);c.drawRect(xB-dp(13),y-dp(33),xB+dp(13),y+dp(33),p);arrow(c,xF,y-dp(90),xF,y-dp(15),Color.rgb(239,68,68),"M="+f(v[0])+" N·m");arrow(c,w*.35f,y+dp(85),w*.35f,y+dp(20),Color.rgb(34,197,94),"T="+f(v[1])+" N·m");arrow(c,xA,y+dp(65),xA,y+dp(20),Color.rgb(59,130,246),"RA");arrow(c,xB,y+dp(65),xB,y+dp(20),Color.rgb(59,130,246),"RB");dim(c,xA,xF,h*.83f,"a="+f(a)+" mm");dim(c,xF,xB,h*.90f,"b="+f(Math.max(0,L-a))+" mm");p.setColor(Color.argb(150,239,68,68));c.drawRect(xF-dp(7),y-dp(28),xF+dp(7),y+dp(28),p);lab(c,"KRİTİK KESİT",xF-dp(35),y-dp(38),Color.rgb(248,113,113));lab(c,"d="+f(v[2])+" mm   Sy="+f(v[3])+" MPa",dp(10),dp(22),Color.WHITE);}void bearing(Canvas c){float w=getWidth(),h=getHeight(),cx=w*.5f,cy=h*.5f,r=Math.min(w,h)*.25f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(16));p.setColor(Color.LTGRAY);c.drawCircle(cx,cy,r,p);p.setStrokeWidth(dp(5));p.setColor(Color.rgb(100,116,139));c.drawCircle(cx,cy,r*.5f,p);p.setStyle(Paint.Style.FILL);for(int k=0;k<10;k++){double a=k*2*Math.PI/10;p.setColor(Color.rgb(203,213,225));c.drawCircle((float)(cx+Math.cos(a)*r*.75),(float)(cy+Math.sin(a)*r*.75),dp(8),p);}arrow(c,cx,dp(20),cx,cy-r-dp(4),Color.rgb(239,68,68),"Fr="+f(v[0])+" N");arrow(c,dp(25),cy,cx-r-dp(4),cy,Color.rgb(59,130,246),"Fa="+f(v[1])+" N");lab(c,"C="+f(v[2])+" N   n="+f(v[3])+" rpm",dp(10),dp(22),Color.WHITE);lab(c,"bore ≈ "+f(v[4])+" mm",dp(10),h-dp(15),Color.rgb(147,197,253));}void bolt(Canvas c){float w=getWidth(),h=getHeight(),y=h*.5f,x1=w*.2f,x2=w*.8f;line(c,Color.LTGRAY,dp(20),x1,y,x2,y);p.setColor(Color.rgb(148,163,184));float t=(float)Math.min(dp(70),Math.max(dp(18),v[4]));c.drawRect(w*.38f,y-t,w*.62f,y+t,p);arrow(c,x2+dp(10),y,x2+dp(75),y,Color.rgb(239,68,68),"F="+f(v[0])+" N");arrow(c,w*.5f,y+dp(90),w*.5f,y+dp(18),Color.rgb(59,130,246),"V="+f(v[1])+" N");p.setColor(Color.argb(150,239,68,68));c.drawRect(w*.61f,y-dp(18),w*.64f,y+dp(18),p);lab(c,"kritik diş/kesit",w*.56f,y-dp(35),Color.rgb(248,113,113));lab(c,"d="+f(v[2])+" mm   Sy="+f(v[3])+" MPa",dp(10),dp(22),Color.WHITE);dim(c,w*.38f,w*.62f,h*.82f,"grip="+f(v[4])+" mm");}}
}
